{
  "name": "expand-range",
  "version": "1.0.0",
  "description": "Expand ranges like '1-10' or 'a-z' into an array of values",
  "type": "module",
  "main": "src/expand-range.js",
  "bin": {
    "expand-range": "bin/expand-range.js"
  },
  "scripts": {
    "start": "node bin/expand-range.js",
    "test": "node --test"
  },
  "license": "MIT"
}

const INTEGER_RE = /^[+-]?\d+$/
const LETTER_RE = /^[A-Za-z]$/

export function expandRange(input, step = 1) {
  if (typeof input !== "string") {
    throw new TypeError("range must be a string")
  }

  const match = input.trim().match(/^(.+?)-(.+)$/)
  if (!match) {
    throw new Error(`invalid range: "${input}"`)
  }

  const start = match[1]
  const end = match[2]

  if (INTEGER_RE.test(start) && INTEGER_RE.test(end)) {
    return expandNumbers(Number(start), Number(end), step)
  }

  if (LETTER_RE.test(start) && LETTER_RE.test(end)) {
    if (start.toLowerCase() !== start && end.toLowerCase() === end) {
      throw new Error(`range endpoints must use the same case: "${input}"`)
    }
    if (start.toLowerCase() === start && end.toLowerCase() !== end) {
      throw new Error(`range endpoints must use the same case: "${input}"`)
    }
    return expandLetters(start, end, step)
  }

  throw new Error(`range endpoints must both be integers or both be single letters: "${input}"`)
}

function expandNumbers(start, end, step) {
  if (!Number.isInteger(step) || step < 1) {
    throw new Error("step must be a positive integer")
  }

  const ascending = start <= end
  const distance = Math.abs(end - start)
  const values = []
  for (let offset = 0; offset <= distance; offset += step) {
    values.push(ascending ? start + offset : start - offset)
  }
  return values
}

function expandLetters(start, end, step) {
  const from = start.codePointAt(0)
  const to = end.codePointAt(0)
  const values = expandNumbers(from, to, step)
  return values.map((code) => String.fromCodePoint(code))
}

#!/usr/bin/env node
import { expandRange } from "../src/expand-range.js"

const [range, step] = process.argv.slice(2)

if (!range) {
  console.error("usage: expand-range <range> [step]")
  console.error("examples: expand-range 1-10  |  expand-range a-z  |  expand-range 10-1 2")
  process.exit(1)
}

try {
  const values = expandRange(range, step ? Number(step) : 1)
  console.log(JSON.stringify(values))
} catch (error) {
  console.error(`error: ${error.message}`)
  process.exit(1)
}

import test from "node:test"
import assert from "node:assert/strict"
import { expandRange } from "../src/expand-range.js"

test("expands ascending integer ranges", () => {
  assert.deepEqual(expandRange("1-5"), [1, 2, 3, 4, 5])
})

test("expands descending integer ranges", () => {
  assert.deepEqual(expandRange("5-1"), [5, 4, 3, 2, 1])
})

test("includes negative numbers", () => {
  assert.deepEqual(expandRange("-3-1"), [-3, -2, -1, 0, 1])
})

test("applies a numeric step", () => {
  assert.deepEqual(expandRange("1-10", 2), [1, 3, 5, 7, 9])
})

test("expands lowercase and uppercase letter ranges", () => {
  assert.deepEqual(expandRange("a-e"), ["a", "b", "c", "d", "e"])
  assert.deepEqual(expandRange("E-A"), ["E", "D", "C", "B", "A"])
})

test("trims surrounding whitespace", () => {
  assert.deepEqual(expandRange(" 3 - 5 "), [3, 4, 5])
})

test("rejects malformed or mismatched ranges", () => {
  assert.throws(() => expandRange("abc"))
  assert.throws(() => expandRange("a-5"))
  assert.throws(() => expandRange("A-z"))
  assert.throws(() => expandRange("1-5", 0))
})

